   209→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   210→    var inp = document.getElementById(wid + "-inp");
   211→    var btn = document.getElementById(wid + "-btn");
   212→    var res = document.getElementById(wid + "-res");
