   214→    if (!inp || !btn || !res) return;
   215→
   216→    function checkZip() {
   217→      var zip = inp.value.trim();
   218→      if (!zip) { inp.focus(); return; }
   219→
   220→      btn.disabled = true;
   221→      btn.textContent = "\u2026";
   222→      res.innerHTML = "";
   223→
   224→      fetch(
   225→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   226→          "&zip=" + encodeURIComponent(zip)
   227→      )
   228→        .then(function (r) { return r.json(); })
   229→        .then(function (data) {
   230→          btn.disabled = false;
   231→          btn.textContent = btnLabel;
   232→
   233→          if (data.allowed) {
   234→            var html = '<div class="zcc-result ok">' + esc(data.message);
   235→            if (cfg.showEta && data.eta) {
   236→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   237→            }
   238→            if (cfg.showZone && data.zone) {
   239→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   240→            }
   241→            if (data.daysOfWeek) {
   242→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   243→              html += '<div class="zcc-meta zcc-days">Delivers: ' + esc(days) + '</div>';
   244→            }
   245→            if (data.cutoffTime) {
   246→              var parts = data.cutoffTime.split(':');
   247→              var hr = parseInt(parts[0], 10);
   248→              var min = parts[1] || '00';
   249→              var ampm = hr >= 12 ? 'PM' : 'AM';
   250→              var hr12 = hr % 12 || 12;
   251→              html += '<div class="zcc-meta zcc-cutoff">Order by ' + hr12 + ':' + min + ' ' + ampm + ' for same-day delivery</div>';
   252→            }
   253→            if (data.codAvailable === true) {
   254→              html += '<div class="zcc-cod zcc-cod--available">\u2713 Cash on Delivery Available</div>';
   255→            } else if (data.codAvailable === false) {
   256→              html += '<div class="zcc-cod zcc-cod--unavailable">\u2717 COD Not Available</div>';
