   490→  function esc(str) {
   491→    return String(str)
   492→      .replace(/&/g, "&amp;")
   493→      .replace(/</g, "&lt;")
   494→      .replace(/>/g, "&gt;")
   495→      .replace(/"/g, "&quot;");
   496→  }
